mapper.select:
select FUTURES_TYPE futuresType, FUTURES_CONTRACT_ID futuresContractId, FUTURES_COMPANY futuresCompany, MST_CUSTOMER_INFO.CUSTOMER_NAME futuresCompanyName, EFF_DATE effDate, DEPOSIT_PERCENT*100 depositPercent from FIN_FUTURE_DEPOSIT_PERCENT LEFT join MST_CUSTOMER_INFO on FIN_FUTURE_DEPOSIT_PERCENT.FUTURES_COMPANY = MST_CUSTOMER_INFO.CUSTOMER_ID
1=1
and FUTURES_TYPE = #{futuresType,jdbcType=VARCHAR}
and FUTURES_CONTRACT_ID = #{futuresContractId,jdbcType=VARCHAR}
and FUTURES_COMPANY = #{futuresCompany,jdbcType=VARCHAR}
and EFF_DATE >= to_date(#{effDateStart},'yyyy-mm-dd')
and EFF_DATE <= to_date(#{effDateEnd},'yyyy-mm-dd')

mapper.update:
update FIN_FUTURE_DEPOSIT_PERCENT


        FUTURES_TYPE = #{futuresType,jdbcType=VARCHAR},


         FUTURES_CONTRACT_ID = #{futuresContractId,jdbcType=VARCHAR},


         FUTURES_COMPANY = #{futuresCompany,jdbcType=VARCHAR},


         EFF_DATE = #{effDate,jdbcType=DATE},


        DEPOSIT_PERCENT = #{depositPercent,jdbcType=DECIMAL},


        UPDATE_USER = #{updateUser,jdbcType=VARCHAR},


        UPDATE_TIME = #{updateTime,jdbcType=TIMESTAMP},



where FUTURES_TYPE = #{futuresType,jdbcType=VARCHAR}
and   FUTURES_CONTRACT_ID = #{futuresContractId,jdbcType=VARCHAR}
and   FUTURES_COMPANY = #{futuresCompany,jdbcType=VARCHAR}
and to_char(EFF_DATE,'yyyy-MM-dd') =#{effDateStr}

